\node (Y2_t1) [below of=Y1_t1] {Y$_2^{1}$};
\node[lagged] (Y2_t2) [right of=Y2_t1] {Y$_2^{2}$};
\node (Y2_t3) [right of=Y2_t2] {Y$_2^{3}$};
\node (Y2_T)  [right=3cm of Y2_t3] {Y$_2^{T}$};

\node (Z1) [left of=Y1_t1] {$Z_1$};
\node (Z2) [left of=Y2_t1] {$Z_2$};

